#!/usr/bin/env python3
from pathlib import Path
import base64, io, tarfile
ROOT=Path(__file__).resolve().parents[1]
PAYLOAD='[... content truncated in conversation due length ...]'
with tarfile.open(fileobj=io.BytesIO(base64.b64decode(PAYLOAD)), mode="r:gz") as tf:
    tf.extractall(ROOT)
for rel in [
    ".github/CODEOWNERS",
    ".github/CODE_OF_CONDUCT.md",
    ".github/CONTRIBUTING.md",
    ".github/SECURITY.md",
    "AUDIT-IMPLEMENTATION.md",
    "PREDEPLOY-READINESS.md",
    "DEPLOYMENT_GUIDE.md",
    "static/css/site.css",
    "static/js/site.js",
    "static/media/icon.png",
    "go.mod",
    "go.sum",
    "config/_default/module.yaml",
]:
    p=ROOT/rel
    if p.exists():
        p.unlink()
for rel in ["scripts/apply_final_refinement.py", ".github/workflows/apply-final-refinement.yaml"]:
    p=ROOT/rel
    if p.exists(): p.unlink()
print("Applied final portfolio refinement payload.")
